import json
from pathlib import Path
ROOT=Path(__file__).resolve().parent.parent
tracks=[];lessons=[]
def module(id,name,icon,description,source):
 tracks.append(dict(id=id,name=name,icon=icon,description=description,formation='DEV',source=source));return id
def q(track,title,theory,code,scenario,question,correct,wrong1,wrong2,explanation):
 n=sum(l['track']==track for l in lessons)+1
 options=[correct,wrong1,wrong2];shift=(len(lessons)+1)%3;options=options[shift:]+options[:shift]
 lessons.append(dict(id=f'{track.lower()}-{n:02}',track=track,formation='DEV',kind='quiz',title=title,theory=theory,code=code,scenario=scenario,question=question,options=options,correct=options.index(correct),explanation=explanation,source=next(t['source'] for t in tracks if t['id']==track)))
API=module('DEV-API','APIs e contratos HTTP','⇄','Desenhe contratos, trate erros e proteja recursos.','https://developer.mozilla.org/en-US/docs/Web/HTTP/Reference')
q(API,'Recursos, requisições e respostas','Uma API define como dois programas conversam. Em HTTP, o cliente envia método, endereço, cabeçalhos e, quando necessário, um corpo. O servidor devolve status, cabeçalhos e representação. Modele o recurso e seu contrato antes de escolher o framework. Uma coleção de pedidos pode ser consultada sem que essa consulta crie novos pedidos.','GET /pedidos?status=aberto\nAccept: application/json\n\nHTTP/1.1 200 OK\n{"items": [{"id": 42, "status": "aberto"}]}','A Loja Horizonte precisa listar pedidos abertos sem modificar nenhum dado.','Qual contrato representa melhor essa operação?','GET /pedidos?status=aberto','POST /pedidos para listar e criar ao mesmo tempo','GET /criar-pedido para aproveitar o cache','GET expressa leitura. Misturar criação com consulta dificulta retries, cache e compreensão do contrato.')
q(API,'Criação e erros que ajudam o cliente','O status HTTP comunica a categoria do resultado; o corpo explica o caso. Uma criação síncrona pode responder 201 e indicar o recurso em Location. Valide os dados no servidor. Um erro de regra não deve virar um 200 com uma mensagem escondida no corpo, nem expor stack traces ou segredos.','POST /pedidos\n{"produtoId": 7, "quantidade": 2}\n\nHTTP/1.1 201 Created\nLocation: /pedidos/42','Um pedido foi validado e gravado antes da resposta.','Qual resposta comunica que um recurso foi criado?','201 Created com identificação do pedido','200 OK sempre, inclusive se a gravação falhar','500 com o stack trace para qualquer erro de entrada','201 comunica criação. O cliente precisa de um identificador estável. Erros de entrada e falhas do servidor devem ter contratos distintos.')
q(API,'Idempotência e retries','Repetir uma chamada pode acontecer porque a resposta se perdeu. Idempotência trata do efeito pretendido após repetições, não de respostas idênticas. Um POST de cobrança precisa de uma estratégia adicional: chave associada ao cliente, armazenamento atômico do resultado e rejeição de reuso com outro conteúdo. A validade da chave deve ser definida.','POST /cobrancas\nIdempotency-Key: compra-42\n{"valorCentavos": 12990}','O pagamento foi aprovado, mas o cliente recebeu timeout e quer tentar novamente.','Como evitar uma cobrança duplicada?','Reusar uma chave e consultar atomicamente o resultado da operação original','Gerar uma chave diferente em cada retry','Fazer retries ilimitados até receber 200','A mesma intenção usa a mesma chave. Uma nova chave representa outra operação e não permite deduplicar a cobrança anterior.')
q(API,'Autenticação não basta: autorize o recurso','Autenticação identifica quem faz a chamada. Autorização decide se essa identidade pode executar a ação sobre aquele recurso. Um ID válido na URL não concede acesso. Busque o pedido no escopo permitido pela sessão, e não por um userId livre enviado pelo cliente. Esconder um botão não protege a API.','// Exemplo conceitual: identidade vem da sessão\nSELECT * FROM pedidos\nWHERE id = :pedido AND dono_id = :usuarioAutenticado;','Um aluno altera /pedidos/42 para /pedidos/43 e encontra o pedido de outra pessoa.','Qual correção resolve a falha de acesso?','Verificar no servidor a relação entre a sessão e o pedido solicitado','Ocultar o ID na tela','Trocar IDs numéricos por UUIDs sem verificar permissão','IDs difíceis de adivinhar ajudam pouco se faltar autorização. Toda leitura ou alteração precisa respeitar o proprietário ou a política de acesso.')
q(API,'Paginação e evolução de contratos','Uma API precisa limitar a quantidade de trabalho por chamada. Use tamanho máximo de página e uma ordenação estável. Em listas mutáveis, um cursor com chave de desempate reduz problemas de deslocamento. Mudar ou remover um campo consumido por clientes é uma quebra de contrato; planeje compatibilidade e período de migração.','GET /pedidos?limit=20&after=cursor-opaco\n{"items": [], "nextCursor": null}','A listagem tem milhares de pedidos, novos registros chegam a cada segundo e vários pedidos têm o mesmo horário.','Qual desenho torna a paginação mais previsível?','Limite de página e ordenação por horário mais ID, refletida no cursor','Retornar todos os pedidos de uma vez','Ordenar apenas pelo horário, sem critério para empates','O desempate estabiliza a ordem. Cursores também precisam de validação e documentação; não substituem autorização nem garantem um snapshot imutável.')
T=module('DEV-TEST','Testes automatizados','✓','Escreva testes de unidade, integração, contrato e jornada.','https://playwright.dev/docs/best-practices')
q(T,'Arrange, Act, Assert','Um teste precisa de preparação controlada, uma ação e uma verificação observável. Testar o comportamento público permite refatorar a implementação sem reescrever todos os testes. Um nome útil descreve a regra e o resultado. Não basta chamar a função: sem uma asserção relevante, uma regressão pode passar despercebida.','// JavaScript ilustrativo\nconst pedido = { total: 100, cupom: 10 }; // Arrange\nconst resultado = calcularTotal(pedido); // Act\nassert.equal(resultado, 90);             // Assert','Uma função aplica um desconto fixo de 10 sobre um total de 100.','Qual teste detecta uma regressão no cálculo?','Verificar que o resultado público é 90','Verificar somente que a função foi chamada','Aguardar dois segundos e encerrar o teste','A asserção verifica a regra. Um teste que apenas executa código pode passar mesmo quando o valor calculado está incorreto.')
q(T,'Limites, classes de equivalência e falhas','Entradas parecidas podem pertencer à mesma classe de comportamento. Escolha representantes e explore fronteiras: vazio, limite mínimo, máximo, valor logo abaixo e logo acima. Teste também rejeições. Cobertura de linhas indica execução, mas não prova que as regras foram verificadas.','// Regra: idade mínima de 18 anos\nassert.equal(podeCadastrar(17), false);\nassert.equal(podeCadastrar(18), true);\nassert.equal(podeCadastrar(19), true);','Um cadastro deve aceitar pessoas a partir de 18 anos.','Qual conjunto procura diretamente um erro de fronteira?','17, 18 e 19','Apenas 30, 40 e 50','Somente verificar 100% de linhas executadas','Os valores próximos à mudança de comportamento detectam >= trocado por >. Entradas inválidas, como números negativos, merecem uma regra própria.')
q(T,'Unidade, integração, contrato e ponta a ponta','Testes de unidade isolam uma regra pequena. Integração verifica componentes reais trabalhando juntos, como SQL e o driver. Contrato verifica o acordo entre consumidores e provedores. Ponta a ponta percorre uma jornada observável. Combine-os pelo risco: muitos E2E lentos não substituem testes rápidos das regras.','Regra de preço → unidade\nRepository + PostgreSQL → integração\nFormato de /pedidos → contrato\nCadastro até compra → ponta a ponta','O código gera uma consulta incompatível com PostgreSQL, mas os testes com um repositório falso passam.','Que teste faltou?','Integração com PostgreSQL e o esquema usados pela aplicação','Mais mocks do mesmo repositório','Um teste que apenas verifica o nome da função','O falso não interpreta SQL como o banco real. Um teste de integração detecta problemas de tipos, constraints e dialeto que o teste de unidade não observa.')
q(T,'Mocks nas fronteiras e relógio controlado','Substitua dependências externas quando precisar controlar tempo, rede ou resultados. Injete um relógio em regras de expiração, em vez de depender da hora real. Muitos mocks de detalhes internos produzem testes frágeis. Um fake deve respeitar o contrato, e integrações reais devem verificar que esse contrato continua válido.','const clock = { now: () => 1000 };\nconst valido = tokenValido({ expiraEm: 1001 }, clock);\nassert.equal(valido, true);','O teste de expiração falha ocasionalmente perto da virada do segundo.','Qual mudança remove a dependência do tempo real?','Injetar um relógio controlável e testar os dois lados da expiração','Aumentar o tempo de espera para um minuto','Executar o teste até passar','Controle o relógio e defina a fronteira de expiração. Repetir até passar esconde a instabilidade e não valida a regra.')
q(T,'Isolamento e pipeline confiável','Testes devem poder rodar sozinhos e em ordem diferente. Use dados próprios por caso e limpe recursos criados. Para uma interface, aguarde um estado observável em vez de um sleep arbitrário. No pipeline, falhas precisam impedir a promoção da versão; retries limitados servem para diagnóstico, não para mascarar regressões.','// Exemplo Playwright\nawait page.getByRole("button", { name: "Salvar" }).click();\nawait expect(page.getByText("Salvo")).toBeVisible();','Um E2E só passa se outro teste tiver criado o usuário antes.','Qual correção torna a suíte independente da ordem?','Preparar o usuário na fixture do próprio teste e isolar seus dados','Fixar a ordem dos arquivos para sempre','Ignorar o teste quando o usuário não existir','Uma fixture explícita remove a dependência oculta. Uma suíte confiável também define limpeza e evita compartilhar estado mutável entre execuções paralelas.')
S=module('DEV-SOLID','SOLID','◇','Pratique os cinco princípios com decisões de código.','https://learn.microsoft.com/dotnet/architecture/modern-web-apps-azure/architectural-principles')
q(S,'S · Responsabilidade única','Responsabilidade única organiza código em torno de razões de mudança relacionadas. Não significa que toda classe só pode ter um método. Uma política de preço muda por regras comerciais; a formatação de um PDF muda por apresentação. Separar essas responsabilidades permite testar e alterar uma sem arrastar a outra.','calcularTotal(pedido)\ngerarRecibo(total, template)\nenviarRecibo(destinatario, documento)','A mesma classe calcula impostos, desenha PDFs e conecta ao SMTP.','Qual separação responde às diferentes razões de mudança?','Extrair cálculo, apresentação e entrega em componentes coesos','Criar uma classe por linha de código','Mover tudo para uma classe chamada Utils','Separar por decisões que mudam juntas reduz acoplamento. Um Utils genérico apenas muda o endereço do problema.')
q(S,'O · Aberto para extensão','Procure um ponto de variação real antes de criar abstrações. Uma política de frete pode ser substituída sem reescrever o fluxo de checkout. Isso não proíbe alterar código existente; orienta a proteger regras estáveis de variações recorrentes. Uma interface sem variação conhecida pode ser custo desnecessário.','function checkout(carrinho, politicaFrete) {\n  return carrinho.total + politicaFrete.calcular(carrinho);\n}','Toda nova transportadora exige editar vários ifs espalhados pelo checkout.','Qual mudança concentra a variação?','Encapsular o cálculo de frete atrás de uma política substituível','Duplicar o checkout para cada transportadora','Adicionar mais condicionais em todas as telas','O checkout depende do comportamento de cálculo. Cada política resolve uma variação; a seleção deve ficar num ponto de composição explícito.')
q(S,'L · Substituição de Liskov','Um subtipo precisa preservar o contrato esperado pelo consumidor: entradas aceitas, resultados garantidos e invariantes. A herança sintática não garante substituição. Se um tipo anuncia gravar(), mas uma variante sempre lança erro por ser somente leitura, o contrato provavelmente está amplo demais.','interface Leitor { ler(id): Documento }\ninterface Gravador { gravar(doc): void }','Um serviço recebe um Gravador, mas uma implementação somente leitura lança “não suportado” em qualquer gravação.','Como expressar melhor os contratos?','Usar um contrato de leitura para o componente que não oferece gravação','Manter Gravador e ignorar todos os erros','Verificar o nome concreto de cada classe em todos os consumidores','A capacidade anunciada precisa existir. Separar contratos evita promessas falsas e condicionais baseadas no tipo concreto.')
q(S,'I · Segregação de interfaces','Consumidores não deveriam depender de operações de que não precisam. Interfaces menores são desenhadas em torno do uso, não de uma regra de quantidade de métodos. Um relatório pode precisar apenas consultar pedidos, sem conhecer cancelamento, cobrança e exportação administrativa.','interface ConsultaPedidos { listar(filtro): Pedido[] }\ninterface CancelaPedido { cancelar(id): void }','Um relatório precisa implementar cancelarPedido porque depende de uma interface gigante.','Qual mudança atende à segregação de interfaces?','Depender somente do contrato de consulta usado pelo relatório','Implementar cancelarPedido vazio para compilar','Fazer o relatório acessar diretamente todas as tabelas','O contrato de consulta expressa a necessidade real. Implementações vazias escondem incompatibilidades e ampliam o acoplamento.')
q(S,'D · Inversão de dependência','Regras de alto nível devem depender de abstrações apropriadas ao problema, e detalhes devem implementá-las. Injetar uma dependência é uma técnica; não basta injetar uma classe concreta acoplada ao fornecedor. O contrato deve descrever o que o caso de uso precisa e não expor objetos do driver.','class FinalizarCompra {\n  constructor(pagamentos) { this.pagamentos = pagamentos; }\n  executar(compra) { return this.pagamentos.cobrar(compra.total); }\n}','Trocar o gateway de pagamento exige alterar regras do domínio porque elas usam tipos do SDK do fornecedor.','Qual limite reduz esse acoplamento?','Um contrato de cobrança do caso de uso, implementado por um adaptador do gateway','Renomear a variável do SDK para interface','Importar o SDK em mais classes para padronizar','O contrato pertence à necessidade da aplicação. O adaptador traduz os tipos externos; a regra não precisa conhecer o fornecedor.')
P=module('DEV-PAT','Design Patterns','⌘','Aplique padrões onde há um problema concreto.','https://learn.microsoft.com/dotnet/architecture/modern-web-apps-azure/architectural-principles')
q(P,'Strategy: algoritmos intercambiáveis','Strategy encapsula maneiras alternativas de executar uma tarefa por um contrato comum. A escolha pode ser feita na composição ou conforme o contexto. É útil quando a política varia independentemente do fluxo principal. Evite usar o padrão só para transformar um if simples em muitas classes sem ganho.','const estrategias = { normal: freteNormal, expresso: freteExpresso };\nconst valor = estrategias[tipo].calcular(pacote);','Você precisa escolher frete normal ou expresso mantendo o mesmo checkout.','Qual padrão encaixa a política variável?','Strategy','Singleton global para todos os cálculos','Observer para substituir um algoritmo síncrono','Strategy oferece implementações alternativas do mesmo comportamento. Observer trata notificações, não a escolha de uma política de cálculo.')
q(P,'Factory: isole a construção','Uma fábrica centraliza a decisão de criar um objeto e montar suas dependências. Uma função fábrica simples não é necessariamente o padrão GoF Factory Method, que delega a criação por uma hierarquia. Escolha o mecanismo mais simples que resolva a variação de construção.','function criarGateway(config) {\n  return config.modo === "teste" ? new GatewayFake() : new GatewayReal(config);\n}','Todas as telas conhecem as chaves e os construtores específicos de gateways.','Onde deve ficar essa construção?','Em um ponto de composição/fábrica que fornece o contrato esperado','Em cada botão da interface','Dentro de todas as entidades de domínio','Centralizar a montagem evita espalhar detalhes do fornecedor. A fábrica não deve virar um local para todas as regras comerciais.')
q(P,'Adapter: traduza contratos incompatíveis','Adapter converte um contrato externo para o contrato que a aplicação entende. Ele traduz nomes, formatos e erros sem espalhar o SDK por todo o sistema. Não esconda diferenças essenciais: se o fornecedor não garante idempotência, o adaptador não pode fingir que garante sem implementar um mecanismo adicional.','class PagamentoAdapter {\n  cobrar(centavos) { return sdk.charge({ amount: centavos, currency: "BRL" }); }\n}','O domínio trabalha em centavos, mas o fornecedor exige um objeto amount/currency.','Qual responsabilidade cabe ao Adapter?','Traduzir o pedido de cobrança para o contrato do SDK','Decidir o limite de crédito do cliente','Armazenar a senha de todos os clientes numa variável global','O Adapter protege a fronteira de integração. Política de crédito pertence ao domínio; conversão de unidades deve ser explícita e testada.')
q(P,'Decorator: componha comportamentos','Decorator envolve um componente mantendo seu contrato e adiciona responsabilidades como medição ou cache. A ordem importa: cache por fora da medição mede algo diferente de medição por fora do cache. Uma implementação precisa preservar semântica de erros, autenticação e cancelamento.','const consulta = comMetricas(comCache(repositorio));\nconst pedido = await consulta.buscar(id);','Você quer medir consultas sem alterar cada implementação de repositório.','Qual desenho permite envolver o contrato existente?','Decorator de métricas delegando a operação ao componente interno','Copiar todo o repositório para adicionar um cronômetro','Adicionar um parâmetro de métricas a cada entidade de domínio','O envoltório mantém o contrato e centraliza uma responsabilidade transversal. Decida se cache hits entram na medição e preserve os erros originais.')
q(P,'Observer e eventos: acoplamento com limites','Observer notifica assinantes quando um evento acontece. Em memória, isso não fornece durabilidade nem entrega após uma queda do processo. Eventos de integração duráveis precisam de armazenamento e uma estratégia de publicação. Evite depender de uma ordem oculta de assinantes para validar invariantes de uma transação.','pedidoConfirmado.subscribe(enviarNotificacao);\npedidoConfirmado.publish({ pedidoId: 42 });','Um processo cai depois de gravar o pedido e antes de notificar os assinantes em memória.','O que o Observer sozinho garante nesse caso?','Não garante entrega após a queda; é preciso um mecanismo durável','Entrega exatamente uma vez em qualquer rede','Rollback automático do pedido gravado','Notificações em memória se perdem com o processo. Uma outbox transacional é uma opção para registrar a intenção de publicar junto com o pedido.')
M=module('DEV-MVC','Arquitetura MVC','▦','Separe entrada, apresentação e regras da aplicação.','https://learn.microsoft.com/aspnet/core/mvc/overview')
q(M,'Model, View e Controller','MVC separa responsabilidades de apresentação e interação. O Controller recebe a entrada e coordena o caso de uso. O Model representa dados e comportamento relevantes, não apenas uma tabela. A View apresenta o resultado. A forma exata varia entre frameworks; o objetivo é evitar regras importantes duplicadas nas telas.','requisição → Controller → caso de uso / Model\nresposta  ← View       ← resultado','Um controller calcula descontos, gera SQL e constrói HTML em uma função de 400 linhas.','Qual primeiro passo melhora a separação?','Extrair a regra de desconto para um componente testável e deixar o controller coordenar','Mover toda a função para a View','Criar três pastas mantendo a mesma função intacta','Pastas não produzem separação por si. Uma regra extraída pode servir à API, à interface e a tarefas agendadas, sem depender do HTTP.')
q(M,'Validação de entrada e regra de negócio','Validação de formato pertence à fronteira: campo obrigatório, tipo e limite de tamanho. Regras como “pedido pago não pode ser cancelado desta forma” precisam existir no domínio ou caso de uso, mesmo quando a chamada não vem da tela. Uma View pode ajudar o usuário, mas nunca é a única barreira.','Controller: valida formato do pedidoId\nCaso de uso: carrega pedido e autoriza ação\nDomínio: verifica se o estado permite cancelar','O botão cancelar está escondido para pedidos pagos, mas uma chamada direta à API consegue cancelá-los.','Onde deve existir a regra que proíbe a transição?','No servidor, no caso de uso/domínio responsável pelo cancelamento','Somente no CSS que esconde o botão','Somente na documentação do frontend','O cliente pode ser alterado ou substituído. O servidor é responsável por autorizar a ação e preservar a regra em qualquer entrada.')
q(M,'DTOs e testes do Controller','Um DTO transporta dados de uma fronteira; não precisa reproduzir todos os campos de uma entidade. Separe o que o cliente pode enviar do que o sistema controla. Teste a tradução entre HTTP e caso de uso e mantenha testes próprios da regra. Evite retornar um objeto que inclui hash de senha por conveniência.','Entrada: { nome, email }\nControlado pelo servidor: { id, perfil, criadoEm }\nSaída: { id, nome }','Um endpoint de cadastro converte automaticamente todo o JSON recebido em campos da entidade, inclusive perfil=admin.','Qual contrato de entrada é mais adequado?','Um DTO com lista explícita dos campos editáveis e autorização separada','Aceitar todos os campos e esconder perfil no formulário','Confiar que o cliente oficial nunca envia perfil','O servidor precisa limitar campos e permissões. Um DTO ajuda a expressar o limite, mas só funciona se o mapeamento realmente ignorar ou rejeitar campos não permitidos.')
V=module('DEV-MVVM','Arquitetura MVVM','◫','Modele estado de tela, bindings e comandos testáveis.','https://learn.microsoft.com/dotnet/architecture/maui/mvvm')
q(V,'ViewModel como estado de apresentação','MVVM usa uma View que observa um ViewModel. O ViewModel expõe estado e ações da tela e depende de contratos de serviços; não precisa conhecer elementos visuais concretos. O Model contém regras e dados do problema. Binding conecta a representação ao estado, mas não elimina a necessidade de definir fluxos de atualização.','View → binding → ViewModel\nViewModel: itens, carregando, erro, comandoBuscar\nViewModel → serviço → domínio','Uma tela precisa mostrar carregamento, erro e lista vazia durante uma busca.','Onde modelar esses estados para testá-los sem renderizar a tela?','No ViewModel, por propriedades e transições explícitas','Em variáveis soltas dentro de cada elemento visual','Em uma tabela de banco chamada cor_do_botao','O estado da apresentação pertence ao ViewModel. Regras de negócio e persistência continuam em componentes próprios.')
q(V,'Comandos e disponibilidade de ações','Um comando representa uma ação do usuário e pode expor se pode executar. Desabilitar o botão durante uma operação evita duplicação acidental na interface, mas não substitui idempotência e validação no servidor. Use try/finally para restaurar o estado de carregamento também quando a operação falha.','async salvar() {\n  if (this.salvando) return;\n  this.salvando = true;\n  try { await servico.salvar(this.formulario); }\n  finally { this.salvando = false; }\n}','A API falha e o botão Salvar fica desabilitado para sempre.','Qual ajuste corrige a transição da tela?','Restaurar salvando em finally e expor o erro ao usuário','Recarregar o banco de dados toda vez','Marcar salvando=false apenas quando o HTTP retornar sucesso','finally executa em sucesso e erro. O estado deve permitir uma tentativa posterior sem ocultar a causa da falha.')
q(V,'Resultados assíncronos fora de ordem','Duas buscas podem terminar em ordem diferente da inicialização. Se o resultado mais antigo substituir o mais recente, a tela mente sobre o filtro atual. Use cancelamento quando suportado e um identificador de geração para aceitar apenas a resposta correspondente à intenção vigente.','const versao = ++this.buscaAtual;\nconst itens = await buscar(texto);\nif (versao === this.buscaAtual) this.itens = itens;','A pessoa busca “ana” e logo “anabela”; a resposta de “ana” chega por último.','Qual atualização deve ser aplicada?','Somente a resposta vinculada à busca atual por anabela','Sempre a última resposta que chegar, independentemente da busca','Misturar as duas listas sem indicar a origem','Ordem de chegada não é ordem de intenção. Um contador por busca permite descartar respostas obsoletas mesmo quando o transporte não consegue cancelar.')
C=module('DEV-CLEAN','Clean Architecture','◎','Proteja regras de negócio das dependências externas.','https://blog.cleancoder.com/uncle-bob/2012/08/13/the-clean-architecture.html')
q(C,'Direção das dependências','Clean Architecture organiza dependências de código para que políticas centrais não dependam de detalhes externos. Interfaces nas fronteiras permitem que adaptadores de banco, HTTP ou mensageria se conectem à aplicação. As camadas não precisam ser processos separados. O valor está nos limites, não em desenhar círculos ou criar dezenas de projetos.','HTTP adapter → casos de uso → domínio\nSQL adapter  → contrato de repositório do núcleo','Uma entidade importa o framework HTTP para obter o usuário da requisição.','Qual alteração respeita a direção das dependências?','Passar ao caso de uso a identidade já validada, sem importar HTTP no domínio','Importar também o driver SQL para centralizar tudo na entidade','Mover o import HTTP para uma pasta chamada domain/infra','O domínio deve receber conceitos relevantes, não uma requisição inteira. A fronteira traduz o protocolo em uma entrada adequada ao caso de uso.')
q(C,'Caso de uso e invariantes','O caso de uso coordena uma intenção: autorizar, carregar estado, aplicar regras e persistir. Entidades e objetos de valor protegem invariantes do domínio. Nem toda aplicação precisa de um modelo complexo; escolha a estrutura que torna as regras explícitas. Evite duplicar a mesma regra em controller, job e consumidor de eventos.','confirmarPedido(identidade, pedidoId)\n  → carregar pedido\n  → verificar permissão\n  → pedido.confirmar()\n  → salvar','A confirmação de pedido pode ocorrer por API ou por processamento de uma fila.','Como manter a regra consistente?','Reusar o mesmo caso de uso e invariantes, com adaptadores de entrada diferentes','Reescrever a regra em cada consumidor','Permitir que cada entrada altere diretamente status no banco','Entradas diferentes traduzem seus formatos, mas convergem para a mesma intenção de negócio. Isso reduz divergências sem obrigar todas as entradas a usar HTTP.')
q(C,'Ports, adapters e composição','Um port é um contrato pelo qual o núcleo conversa com o exterior. Um adapter implementa ou chama esse contrato usando uma tecnologia concreta. A composição liga as peças em runtime. Essa separação permite testar uma regra com um fake e verificar o adaptador real com testes de integração.','const repo = new SqlPedidos(pool);\nconst confirmar = new ConfirmarPedido(repo);\nconst controller = new PedidoController(confirmar);','Você quer testar a regra de confirmação sem rede nem banco.','Qual dependência usar no teste de unidade?','Um repositório fake que respeita o contrato, com testes separados do adapter SQL','Um PostgreSQL obrigatório em cada teste de cálculo','O controller HTTP como substituto da entidade','O fake reduz o escopo do teste de regra. Ele não prova que SQL ou mapeamento funcionam; isso exige um teste de integração complementar.')
q(C,'Transações atravessam decisões de arquitetura','Uma transação precisa abranger as alterações que devem ser atômicas dentro do mesmo banco. O caso de uso define essa necessidade; a infraestrutura fornece o mecanismo. Chamadas externas, como envio de e-mail, não voltam no tempo quando o banco faz rollback. Registre uma intenção durável se o efeito externo deve acompanhar o commit.','transação {\n  salvarPedido(pedido);\n  registrarOutbox("PedidoConfirmado", pedido.id);\n}\n// publicação ocorre depois, com retries','O banco confirma o pedido, mas a publicação do evento falha.','Qual desenho evita perder a intenção de publicar?','Gravar pedido e outbox na mesma transação e publicar depois','Publicar primeiro e presumir que o commit sempre funcionará','Fazer um rollback no banco após enviar o e-mail e considerar tudo desfeito','A outbox mantém o evento pendente de forma durável. O consumidor ainda deve lidar com duplicatas; a publicação posterior pode ocorrer mais de uma vez.')
N=module('DEV-TENANT','Arquitetura Multi Tenant','▧','Isole organizações em dados, cache, filas e operação.','https://learn.microsoft.com/en-us/azure/architecture/guide/multitenant/considerations/tenancy-models')
q(N,'Tenant, usuário e isolamento','Um tenant é uma fronteira de cliente ou organização, não necessariamente um único usuário. Uma pessoa pode participar de vários tenants com permissões diferentes. A aplicação deve validar a associação e a ação no tenant ativo. Um tenantId enviado pelo navegador representa uma escolha a validar, não uma autoridade.','sessão autenticada + tenant escolhido\n  → verificar associação e papel\n  → criar contexto autorizado\n  → executar caso de uso','Uma pessoa da empresa Azul troca tenantId para o ID da empresa Verde.','O que o servidor deve fazer antes de consultar dados?','Verificar se a identidade tem acesso ao tenant Verde e à ação solicitada','Aceitar o tenantId porque o usuário está autenticado','Validar apenas se o ID tem formato UUID','Autenticação não prova associação a todas as organizações. O contexto do tenant precisa ser autorizado antes da consulta e propagado com limites claros.')
q(N,'Modelos de armazenamento e trade-offs','Tabelas compartilhadas com tenant_id favorecem consolidação, mas exigem filtragem consistente. Schemas ou bancos separados podem facilitar isolamento e restauração por cliente, com maior custo operacional. A escolha depende do nível de isolamento, migrações, escala e recuperação. Nenhum modelo dispensa autorização da aplicação.','Compartilhado: pedidos(tenant_id, id, total)\nSeparado: banco_azul.pedidos / banco_verde.pedidos','Um cliente exige restauração independente e isolamento operacional forte; a equipe aceita maior custo de operação.','Qual opção merece avaliação?','Banco separado por tenant, considerando migrações e custo','Uma única tabela sem tenant_id','Apenas acrescentar o nome da empresa no título da tela','Separar bancos pode atender à recuperação e ao isolamento, mas não elimina custos de migração, conexões, monitoramento e autorização.')
q(N,'Escopo também em cache e jobs','O tenant precisa acompanhar cada fronteira: consulta, chave de cache, mensagem, arquivo e tarefa agendada. Um cache pedido:42 pode devolver dados de outra organização se IDs forem locais ao tenant. Workers devem validar o contexto da tarefa e usar credenciais/consultas compatíveis com esse escopo.','chave = `tenant:${tenantId}:pedido:${pedidoId}`;\njob = { tenantId, pedidoId, operacao: "emitirRecibo" };','Duas empresas têm um pedido 42, mas o cache usa somente pedido:42.','Qual correção elimina a colisão entre tenants?','Incluir o tenant autorizado na chave e manter a autorização na leitura','Aumentar o TTL do cache','Usar uma variável global com o último tenant acessado','O cache deve refletir o escopo do recurso. Uma variável global causa vazamentos entre requisições; a chave correta não substitui a verificação de permissão.')
q(N,'Testes negativos e noisy neighbor','Isolamento deve ser testado com pelo menos dois tenants e tentativas de acesso cruzado. Inclua listagem, exportação, cache e tarefas em segundo plano. Além de confidencialidade, pense em recursos: um cliente pode consumir todas as conexões. Limites, filas justas e métricas por tenant ajudam a conter esse impacto.','Teste: usuário Azul tenta ler pedido Verde → negado\nTeste: exportação Azul → nenhum registro Verde\nMétrica: tempo de fila por tenant','Uma empresa dispara milhares de relatórios e deixa todas as outras sem conexões.','Qual medida trata esse problema de compartilhamento?','Cotas e concorrência limitada por tenant, com observação da fila','Permitir acesso aos dados de outros tenants para agilizar','Apenas mudar o logotipo de cada cliente','Noisy neighbor é disputa por recursos. Limites e agendamento por tenant controlam o impacto; também é preciso dimensionar capacidade e monitorar o comportamento.')
D=module('DEV-DDD','Domain Driven Design','⬡','Modele linguagem, contextos, agregados e eventos.','https://learn.microsoft.com/en-us/azure/architecture/microservices/model/domain-analysis')
q(D,'Linguagem ubíqua e descoberta do domínio','DDD começa pela compreensão do negócio com as pessoas que o conhecem. Linguagem ubíqua significa usar termos consistentes em conversas, exemplos, testes e código dentro de um contexto. Um glossário não basta se o código ignora as regras. Pergunte por eventos, exceções e decisões antes de desenhar entidades.','PedidoRascunho → confirmar() → PedidoConfirmado\nExemplo: pedido sem itens não pode ser confirmado.','Especialistas dizem “reserva”, mas o código chama a mesma coisa de “compra finalizada”, causando erros de cobrança.','Qual ação inicia uma modelagem melhor?','Alinhar o significado dos termos com exemplos e regras antes de renomear/modelar','Criar um microsserviço para cada substantivo','Copiar as tabelas atuais e chamar isso de domínio','Os nomes precisam refletir o comportamento real. Entender quando uma reserva vira compra evita unificar conceitos com ciclos de vida diferentes.')
q(D,'Bounded Context e significados locais','Um bounded context delimita onde um modelo e sua linguagem têm significado consistente. O mesmo termo pode representar coisas diferentes em contextos distintos. “Cliente” em faturamento e atendimento não precisa ser uma entidade universal gigante. A integração exige um contrato e tradução explícita quando os modelos diferem.','Faturamento: ClienteFiscal(documento, endereçoFiscal)\nAtendimento: Contato(preferências, canais)','Faturamento precisa de dados fiscais; atendimento precisa de preferências de contato.','Qual desenho evita um modelo universal cheio de regras incompatíveis?','Modelos próprios por contexto com integração explícita','Uma tabela única obrigatória para todo significado de cliente','Um contexto por coluna de banco','O limite protege o significado do modelo. Contextos podem existir no mesmo processo; não obrigam uma implantação distribuída.')
q(D,'Entidade e objeto de valor','Uma entidade mantém identidade ao longo de mudanças. Um objeto de valor é definido por seus atributos e normalmente é tratado como imutável. Dinheiro precisa de valor e moeda; somar moedas diferentes sem conversão deve ser impedido. Escolha o modelo pelas regras, não pela presença de uma chave na tabela.','Dinheiro(1000, "BRL") + Dinheiro(500, "BRL")\n→ Dinheiro(1500, "BRL")\n// BRL + USD exige uma política de conversão','Dois endereços com exatamente os mesmos campos não precisam ser distinguidos por identidade no seu domínio.','Qual modelagem é uma boa candidata?','Objeto de valor comparado pelos atributos','Entidade global com identidade obrigatória em todos os sistemas','String sem validação, mesmo com regras de endereço','Objeto de valor expressa igualdade pelo conteúdo e pode validar invariantes. Em outro domínio um endereço poderia ter identidade; a decisão depende do significado.')
q(D,'Agregados e consistência','Um agregado define um limite de consistência e tem uma raiz que controla alterações relevantes. O tamanho deve ser suficiente para preservar invariantes, sem carregar todo o sistema numa transação. Referências a outros agregados costumam usar identidade. Concorrência ainda exige estratégia, como versão otimista ou bloqueio adequado.','pedido.adicionarItem(produtoId, quantidade)\npedido.confirmar() // verifica itens e total\nrepository.salvar(pedido, versaoEsperada)','Um pedido confirmado não pode ter quantidade negativa em seus itens.','Qual papel cabe à raiz Pedido?','Controlar alterações dos itens e validar a invariante no limite do agregado','Permitir atualizações independentes irrestritas em qualquer item','Carregar todos os clientes e produtos em um único agregado','A raiz oferece operações válidas em vez de setters sem restrição. A persistência precisa detectar conflitos para preservar as regras sob concorrência.')
q(D,'Eventos de domínio e tradução externa','Um evento de domínio descreve algo relevante que aconteceu, geralmente no passado. Ele pode disparar reações internas. Um evento de integração cruza uma fronteira e precisa de contrato estável, versionamento e estratégia de entrega. Não publique toda a entidade interna: isso acopla consumidores a detalhes e pode expor dados indevidos.','PedidoConfirmado { pedidoId, confirmadoEm }\n// Contrato externo seleciona somente dados necessários.','Um time quer publicar o objeto Pedido inteiro para todos os sistemas porque é mais fácil serializar.','Qual alternativa reduz acoplamento e exposição?','Definir um evento de integração explícito com os dados necessários aos consumidores','Enviar também credenciais para facilitar o consumo','Obrigar consumidores a ler as tabelas internas','O contrato externo precisa ser deliberado. Mudanças no modelo interno não deveriam quebrar todos os consumidores ou revelar informação que eles não precisam.')
R=module('DEV-MICRO','Microsserviços','⤴','Entenda limites, falhas parciais e consistência distribuída.','https://learn.microsoft.com/en-us/azure/architecture/microservices/model/tactical-ddd')
q(R,'Quando distribuir e quando manter módulos','Microsserviços separam unidades de implantação e responsabilidade. Isso pode permitir evolução e escala independentes, mas adiciona rede, observabilidade, versionamento e falhas parciais. Um monólito modular permite limites claros sem esses custos iniciais. DDD não obriga um serviço por entidade nem por contexto em qualquer situação.','Monólito modular: catálogo | pedidos | cobrança\nExtração possível: cobrança, quando houver motivo operacional','Um time de três pessoas está descobrindo o produto e não tem necessidade comprovada de deploy independente.','Qual ponto de partida merece consideração?','Monólito modular com limites explícitos e possibilidade de extração futura','Dezenas de serviços desde o primeiro dia por padrão','Um serviço separado para cada coluna do banco','Separar módulos preserva opções sem antecipar todos os custos de distribuição. A extração deve responder a uma necessidade concreta de operação ou evolução.')
q(R,'Comunicação e falhas parciais','Uma chamada remota pode falhar depois que o destino executou a operação. Defina timeouts, limites de concorrência e retries somente quando a repetição for adequada. Backoff com jitter reduz sincronização das tentativas. Cadeias síncronas longas aumentam dependências de disponibilidade e latência.','pedido → cobrança (timeout definido)\nretry: limitado + backoff + idempotência\nobservação: resultado pode ser desconhecido','Uma cobrança remota dá timeout depois que a conexão já enviou o pedido ao serviço de pagamentos.','Qual conclusão é correta?','O resultado pode ser desconhecido; é preciso consultar ou repetir de forma idempotente','A cobrança certamente não aconteceu','É seguro repetir indefinidamente com nova chave','Timeout diz que o cliente não obteve a resposta a tempo. Não prova que o servidor não concluiu; a estratégia deve contemplar esse estado intermediário.')
q(R,'Dados pertencem a um serviço','Quando todos os serviços alteram as mesmas tabelas, mudanças de esquema exigem coordenação e enfraquecem autonomia. Cada serviço deve controlar seu modelo e expor contratos apropriados. Relatórios podem usar projeções ou pipelines de dados, com atraso explícito. Não prometa consistência instantânea se a atualização é assíncrona.','Pedidos → publica PedidoConfirmado\nRelatórios → atualiza projeção de vendas\nTela → informa horário de atualização','O serviço de relatório atualiza diretamente tabelas privadas de cobrança.','Que limite deve ser restabelecido?','Cobrança controla as escritas; integração usa contratos ou projeções apropriadas','Todos os serviços recebem a senha de superusuário do banco','Remover constraints para qualquer escrita ser aceita','Propriedade de dados organiza responsabilidade e evolução. Projeções podem servir leituras sem transferir a autoridade de alterar o estado de cobrança.')
q(R,'Saga e compensação','Uma saga coordena etapas locais com ações de compensação quando necessário. Compensar não é um rollback mágico: pode haver efeitos irreversíveis, custos e intervenção humana. Cada etapa precisa de idempotência, identificação e estado observável. Defina o que fazer quando a própria compensação falha.','reservar estoque → cobrar → confirmar pedido\nfalha na cobrança → liberar reserva\nfalha na liberação → registrar pendência e tentar novamente','O estoque foi reservado, mas o pagamento foi recusado.','Qual reação faz sentido numa saga de compra?','Executar uma compensação de liberação, com registro e retries limitados','Presumir rollback automático em todos os bancos','Apagar silenciosamente os logs da reserva','A compensação é uma operação de negócio que pode falhar. Estado e histórico permitem recuperar o fluxo sem fingir atomicidade global.')
q(R,'Outbox, duplicatas e rastreamento','A outbox grava o evento junto com a mudança de negócio numa transação local. Um publicador entrega depois; se a confirmação se perde, pode publicar novamente. Consumidores precisam de deduplicação ou operações idempotentes. Correlation IDs ajudam a seguir o fluxo, mas não substituem métricas de resultado nem decisões de consistência.','transação: salvarPedido + outbox(eventId)\npublicador: enviar → marcar como enviado\nconsumidor: aplicar uma vez por eventId no escopo correto','O publicador envia um evento e cai antes de marcar a outbox como enviada.','Como o consumidor deve lidar com a nova entrega?','Reconhecer a identidade do evento e evitar repetir o efeito indevidamente','Assumir entrega exatamente uma vez por usar uma fila','Gerar um novo pedido para cada mensagem recebida','Entrega repetida é esperada nesse desenho. O registro de deduplicação e o efeito precisam ter consistência adequada, evitando marcar processado antes de concluir a operação.')
SQL=module('DEV-SQL','SQL na prática','▱','Execute consultas e transações em um banco de laboratório.','https://www.sqlite.org/lang.html')
setup="""PRAGMA foreign_keys=ON;
CREATE TABLE clientes(id INTEGER PRIMARY KEY,nome TEXT NOT NULL,tenant_id TEXT NOT NULL);
CREATE TABLE pedidos(id INTEGER PRIMARY KEY,cliente_id INTEGER REFERENCES clientes(id),total INTEGER NOT NULL CHECK(total>=0),status TEXT NOT NULL);
CREATE TABLE contas(id INTEGER PRIMARY KEY,saldo INTEGER NOT NULL CHECK(saldo>=0));
INSERT INTO clientes VALUES(1,'Ana','azul'),(2,'Bruno','azul'),(3,'Carla','verde'),(4,'Davi','verde');
INSERT INTO pedidos VALUES(101,1,120,'pago'),(102,1,80,'aberto'),(103,2,200,'pago'),(104,3,50,'pago'),(105,3,150,'aberto');
INSERT INTO contas VALUES(1,100),(2,50);
"""
def sql(title,theory,code,scenario,question,solution,check=None):
 n=sum(l['track']==SQL for l in lessons)+1
 lessons.append(dict(id=f'dev-sql-{n:02}',track=SQL,formation='DEV',kind='sql',title=title,theory=theory,code=code,scenario=scenario,question=question,solution=solution,checkQuery=check,source='https://www.sqlite.org/lang.html',explanation='Confira os nomes das colunas, a ordenação e todas as linhas do resultado. Cada execução começa com o banco original; suas consultas nunca acessam contas do Aurora.'))
sql('SELECT: escolha as colunas','SELECT projeta as colunas que você quer ler. FROM escolhe a tabela. A ordem das linhas não é garantida sem ORDER BY. Escolher colunas explicitamente deixa o contrato da consulta mais claro do que depender de SELECT *. Neste laboratório, os valores monetários são inteiros didáticos.','SELECT id, nome FROM clientes ORDER BY id;','Você precisa mostrar o nome dos clientes em ordem alfabética.','Retorne somente a coluna nome de todos os clientes, em ordem alfabética crescente.','SELECT nome FROM clientes ORDER BY nome;')
sql('WHERE: filtre antes de apresentar','WHERE seleciona linhas com base numa condição. Combine AND e OR com parênteses para expressar prioridade. Valores vindos de usuários devem ser parâmetros do driver em uma aplicação real; concatenar entrada em SQL pode permitir injeção. Aqui os dados do exercício são fixos.','SELECT id FROM pedidos WHERE status = \'aberto\' ORDER BY id;','O financeiro quer identificar os pedidos pagos de pelo menos 100 unidades.','Retorne id e total dos pedidos com status pago e total >= 100, em ordem de id crescente.','SELECT id, total FROM pedidos WHERE status = \'pago\' AND total >= 100 ORDER BY id;')
sql('JOIN: relacione clientes e pedidos','INNER JOIN combina linhas conforme uma condição. Use a chave de relacionamento; esquecer a condição pode multiplicar linhas em um produto cartesiano. Qualifique colunas quando houver nomes iguais. Uma chave estrangeira protege referências, mas não define automaticamente a consulta que você precisa.','SELECT p.id, c.nome\nFROM pedidos p JOIN clientes c ON c.id = p.cliente_id;','O suporte precisa identificar quem fez cada pedido pago.','Retorne id do pedido (coluna id) e nome do cliente (coluna nome) para pedidos pagos, em ordem de id do pedido.','SELECT p.id AS id, c.nome AS nome FROM pedidos p JOIN clientes c ON c.id=p.cliente_id WHERE p.status=\'pago\' ORDER BY p.id;')
sql('GROUP BY e HAVING: agregue resultados','GROUP BY define grupos para agregações como SUM e COUNT. WHERE filtra linhas antes do agrupamento; HAVING filtra os grupos calculados. Ao selecionar colunas não agregadas, inclua as chaves apropriadas no agrupamento. Não confie em permissividades específicas de um dialeto para escolher um valor arbitrário.','SELECT cliente_id, SUM(total) AS total_pago\nFROM pedidos WHERE status = \'pago\'\nGROUP BY cliente_id;','Você quer clientes com pelo menos 100 unidades em pedidos pagos.','Retorne cliente_id e SUM(total) com alias total_pago; considere somente pagos, mantenha grupos >= 100 e ordene por cliente_id.','SELECT cliente_id,SUM(total) AS total_pago FROM pedidos WHERE status=\'pago\' GROUP BY cliente_id HAVING SUM(total)>=100 ORDER BY cliente_id;')
sql('LEFT JOIN e NULL: encontre ausências','LEFT JOIN preserva linhas da tabela à esquerda mesmo sem correspondência à direita. Quando não há correspondência, as colunas da direita são NULL. Use IS NULL para verificar ausência; = NULL não é uma comparação verdadeira. Filtrar a tabela da direita em WHERE pode eliminar linhas que você pretendia preservar.','SELECT c.nome, p.id\nFROM clientes c LEFT JOIN pedidos p ON p.cliente_id=c.id;','A equipe quer convidar os clientes que ainda não fizeram nenhum pedido.','Retorne apenas nome dos clientes sem pedidos, em ordem alfabética.','SELECT c.nome AS nome FROM clientes c LEFT JOIN pedidos p ON p.cliente_id=c.id WHERE p.id IS NULL ORDER BY c.nome;')
sql('Transações: altere e reverta com intenção','BEGIN inicia uma transação; COMMIT confirma e ROLLBACK desfaz suas alterações ainda não confirmadas. Uma transferência precisa debitar e creditar no mesmo limite atômico. Constraints e checagem de saldo protegem invariantes. O laboratório usa SQLite; níveis de isolamento e concorrência variam entre bancos.','BEGIN;\nUPDATE contas SET saldo = saldo - 10 WHERE id = 1;\nUPDATE contas SET saldo = saldo + 10 WHERE id = 2;\nCOMMIT;','Transfira 30 unidades da conta 1 para a 2. Em seguida simule um débito adicional de 10 na conta 1 e desfaça apenas essa segunda operação.','Execute duas transações: confirme a transferência de 30 e reverta o débito de teste. O verificador lerá id e saldo das contas; o estado final deve ser 70 e 80.','BEGIN; UPDATE contas SET saldo=saldo-30 WHERE id=1; UPDATE contas SET saldo=saldo+30 WHERE id=2; COMMIT; BEGIN; UPDATE contas SET saldo=saldo-10 WHERE id=1; ROLLBACK;','SELECT id,saldo FROM contas ORDER BY id;')
assert len(lessons)==50,len(lessons)
(ROOT/'public/developer.json').write_text(json.dumps(dict(tracks=tracks,lessons=lessons,sqlSetup=setup),ensure_ascii=False,indent=2),encoding='utf-8')
old=json.loads((ROOT/'public/curriculum.json').read_text(encoding='utf-8-sig'))
ids=[l['id'] for l in old['lessons']]+[f'linux-{i}' for i in range(18)]+[l['id'] for l in lessons]
(ROOT/'lib/lesson-ids.json').write_text(json.dumps(ids),encoding='utf-8')
print(f'{len(tracks)} módulos, {len(lessons)} aulas de desenvolvimento; {len(ids)} atividades no total.')

